from pathlib import Path
import base64,gzip
ROOT=Path("android")
HTML=ROOT/"app/src/main/assets/index.html"
GRADLE=ROOT/"app/build.gradle"
ACTIVITY=ROOT/"app/src/main/java/com/zarivostudios/prismhop/MainActivity.java"
def dec(v): return gzip.decompress(base64.b64decode(v)).decode()
CSS=dec("")
PRE=dec("H4sIAEtAq2oC/22PwQrCMBBE7/2KekpyaA8eLfGmUBAU+gElpKsNpokkW0sp/XeTqBfxsswOb2bZjFLG90uW59Iaj/kdZk4eTvmh6O2jeG53Hq2ba4PONgCGVAHVgPlVOY8c3QjRQTcvb0dbKXQTMuIG5Q2wRhhoaGUbzknESbVKgbJf1pCblOnsVLbtJZ6MsfkYa05iNLLnqbL6z50n438xdaVJs87KcQCD5VccNKRdauH9SXksRdfRz6fpxSIlCauyldEwX6T0ryQaAQAA")
CTRL=dec("")
STORY=dec("")
SETTINGS='      <section class="story-settings" aria-labelledby="story-settings-title">\n        <h3 id="story-settings-title">Story / About</h3>\n        <p>Return to the beginning and replay <strong>The Shattering</strong>. This cinematic is local and does not affect your progress, Daily Race or Spotlight.</p>\n        <button type="button" id="replay-story">Replay The Shattering</button>\n        <small id="story-replay-status"></small>\n      </section>\n'
s=HTML.read_text()
def rep(old,new,label):
    global s
    if old not in s: raise SystemExit("missing "+label)
    s=s.replace(old,new,1)
rep("app_version:(window.PrismNative?'3.8.0-android':'3.4.0-web')","app_version:(window.PrismNative?'3.9.0-android':'3.4.0-web')","client version")
rep("</head>",f'<script id="v390-story-preflight">\n{PRE}\n</script>\n<style id="v390-story-style">\n{CSS}\n</style>\n</head>',"head")
main='<main class="game startup-active" id="game" aria-label="Prism Hop game">'
rep(main,main+"\n  "+STORY,"story mount")
rep('<details class="typography-settings">',SETTINGS+'<details class="typography-settings">',"settings")
rep('<script id="v3311-connected-launch">',f'<script id="v390-story-controller">\n{CTRL}\n</script>\n<script id="v3311-connected-launch">',"controller")
rep("<script id=\"v3311-connected-launch\">\n(()=>{\n  const splash=document.getElementById('startup-splash');","<script id=\"v3311-connected-launch\">\n(()=>{\n  if(window.__PrismStoryOwnsLaunch)return;\n  const splash=document.getElementById('startup-splash');","launch guard")
HTML.write_text(s)
g=GRADLE.read_text()
if 'versionCode 40' not in g or "versionName '3.8.0-test'" not in g: raise SystemExit('bad gradle base')
GRADLE.write_text(g.replace('versionCode 40','versionCode 41',1).replace("versionName '3.8.0-test'","versionName '3.9.0-test'",1))
a=ACTIVITY.read_text()
mark='private static final String APP_VERSION = "3.8.0-test";'
if mark not in a: raise SystemExit('bad activity base')
ACTIVITY.write_text(a.replace(mark,'private static final String APP_VERSION = "3.9.0-test";',1))
raw=HTML.read_bytes()
(ROOT/'app/src/main/assets/index.html.gz.b64').write_text(base64.b64encode(gzip.compress(raw,9)).decode())
print('V3.9 story intro applied:',len(raw),'bytes')
